describe('openColorbox_function', () => {
  beforeEach(() => {
    KeepTrack.getInstance().containerRoot = document.body as HTMLDivElement;
    KeepTrack.getDefaultBodyHtml();
    KeepTrack.getInstance().containerRoot.innerHTML = `
        <div id="colorbox-container" style="display:none;"></div>
        <div id="colorbox-header"></div>
        <div id="colorbox-div" style="display:block;"></div>
        <div id="colorbox-iframe" style="display:none;"></div>
        <div id="colorbox-img" style="display:none;"></div>
        `;
  });

  // Tests that a colorbox is created if it does not exist
  it('test_create_colorbox', () => {
    getEl('colorbox-div')!.remove();
    const colorboxDiv = getEl('colorbox-div', true);

    expect(colorboxDiv).toBeNull();

    // jest replace getEl function
    vi.spyOn(getElAll, 'getEl').mockImplementationOnce(() => <HTMLElement>getEl('colorbox-div'));

    openColorbox('https://www.example.com');
    const newColorboxDiv = getEl('colorbox-div');

    expect(newColorboxDiv).not.toBeNull();
  });

  // Tests that loading overlay is shown before opening the colorbox
  it('test_show_loading', () => {
    openColorbox('https://www.example.com');
    const overlay = document.getElementById('loading-overlay');

    expect(overlay).not.toBeNull();
    expect(overlay!.style.display).toBe('flex');
  });

  // Tests that colorbox is displayed after loading screen disappears
  it('test_display_colorbox', () => {
    let colorboxDiv = <HTMLElement>getEl('colorbox-div');

    openColorbox('https://www.example.com');
    vi.advanceTimersByTime(2000);
    colorboxDiv = <HTMLElement>getEl('colorbox-div');
    expect(colorboxDiv.style.display).toBe('block');
  });

  // Tests that image colorbox is set up if options.image is true
  it('test_setup_image_colorbox', () => {
    // jest replace getEl function
    vi.spyOn(getElAll, 'getEl').mockImplementationOnce(() => <HTMLElement>getEl('colorbox-div'));

    openColorbox('https://www.example.com', { image: true });
    vi.advanceTimersByTime(2000);

    const colorboxContainer = <HTMLElement>getEl('colorbox-container');

    expect(colorboxContainer.style.transform).toBe('translateX(-200%)');
    const colorboxIframe = <HTMLElement>getEl('colorbox-iframe');

    expect(colorboxIframe.style.display).toBe('none');
    const colorboxImg = <HTMLImageElement>getEl('colorbox-img');

    expect(colorboxImg.style.display).toBe('block');
    expect(colorboxImg.src).toBe('https://www.example.com');
  });

  // Tests that iframe colorbox is set up if options.image is false
  it('test_setup_iframe_colorbox', () => {
    // jest replace getEl function
    vi.spyOn(getElAll, 'getEl').mockImplementationOnce(() => <HTMLElement>getEl('colorbox-div'));

    openColorbox('https://www.example.com', { image: false });
    vi.advanceTimersByTime(2000);

    const colorboxIframe = <HTMLIFrameElement>getEl('colorbox-iframe');

    expect(colorboxIframe.style.display).toBe('block');
    expect(colorboxIframe.src).toBe('https://www.example.com');
    const colorboxImg = <HTMLElement>getEl('colorbox-img');

    expect(colorboxImg.style.display).toBe('none');
  });

  // Image load failures toast the caller's message (e.g. naming the source) and keep the URL for the console
  it('test_image_error_uses_custom_message', () => {
    const warn = vi.spyOn(errorManagerInstance, 'warn').mockImplementation(() => undefined);

    openColorbox('https://www.example.com/a.jpg', { image: true, imageErrorMessage: 'Could not load the Example image' });
    vi.advanceTimersByTime(2000);
    (<HTMLImageElement>getEl('colorbox-img')).onerror!(new Event('error'));

    expect(warn).toHaveBeenCalledWith('Could not load the Example image', 'https://www.example.com/a.jpg');
    warn.mockRestore();
  });

  // Without a custom message the generic text names the URL
  it('test_image_error_default_message', () => {
    const warn = vi.spyOn(errorManagerInstance, 'warn').mockImplementation(() => undefined);

    openColorbox('https://www.example.com/b.jpg', { image: true });
    vi.advanceTimersByTime(2000);
    (<HTMLImageElement>getEl('colorbox-img')).onerror!(new Event('error'));

    expect(warn).toHaveBeenCalledTimes(1);
    expect(warn.mock.calls[0][0]).toContain('https://www.example.com/b.jpg');
    warn.mockRestore();
  });

  // Tests that colorbox is closed when clicked
  it('test_close_colorbox', () => {
    // Create a spyon
    const cb = vi.fn();

    openColorbox('https://www.example.com', { callback: cb });
    vi.advanceTimersByTime(2000);

    const colorboxDom = <HTMLElement>getEl('colorbox-div');

    expect(colorboxDom.style.display).toBe('block');
    colorboxDom.click();
    vi.advanceTimersByTime(1000);

    expect(cb).toHaveBeenCalled();
  });
});

describe('colorbox new tab and blank-page hint', () => {
  beforeEach(() => {
    KeepTrack.getInstance().containerRoot = document.body as HTMLDivElement;
    KeepTrack.getInstance().containerRoot.innerHTML = '';
    createColorbox();
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  const hint = () => <HTMLElement>getEl('colorbox-hint');
  const openButton = () => <HTMLButtonElement>getEl('colorbox-open-button');

  it('opens the iframe source in a new tab with noopener,noreferrer', () => {
    const open = vi.spyOn(window, 'open').mockImplementation(() => null);

    openColorbox('https://www.example.com/page.htm');
    vi.advanceTimersByTime(2000);
    openButton().click();

    expect(open).toHaveBeenCalledWith('https://www.example.com/page.htm', '_blank', 'noopener,noreferrer');
  });

  it('opens an image source in a new tab with noopener,noreferrer', () => {
    const open = vi.spyOn(window, 'open').mockImplementation(() => null);

    openColorbox('https://www.example.com/a.jpg', { image: true });
    vi.advanceTimersByTime(2000);
    openButton().click();

    expect(open).toHaveBeenCalledWith('https://www.example.com/a.jpg', '_blank', 'noopener,noreferrer');
  });

  it('the new-tab button follows the iframe again after an image colorbox', () => {
    const open = vi.spyOn(window, 'open').mockImplementation(() => null);

    openColorbox('https://www.example.com/a.jpg', { image: true });
    vi.advanceTimersByTime(2000);
    openColorbox('https://www.example.com/page.htm');
    vi.advanceTimersByTime(2000);
    openButton().click();

    expect(open).toHaveBeenLastCalledWith('https://www.example.com/page.htm', '_blank', 'noopener,noreferrer');
  });

  it('shows the blank-page hint for an external iframe', () => {
    openColorbox('https://www.example.com/page.htm');
    vi.advanceTimersByTime(2000);

    expect(hint().style.display).toBe('inline');
    expect(hint().textContent).toBe('Page blank? Open it in a new tab.');
  });

  it('hides the hint for a same-origin iframe and for images', () => {
    openColorbox(`${window.location.origin}/local.html`);
    vi.advanceTimersByTime(2000);
    expect(hint().style.display).toBe('none');

    openColorbox('https://www.example.com/page.htm');
    vi.advanceTimersByTime(2000);
    openColorbox('https://www.example.com/a.jpg', { image: true });
    vi.advanceTimersByTime(2000);
    expect(hint().style.display).toBe('none');
  });

  it('a click on the hint does not close the colorbox', () => {
    openColorbox('https://www.example.com/page.htm');
    vi.advanceTimersByTime(2000);
    hint().click();
    vi.advanceTimersByTime(1000);

    expect((<HTMLElement>getEl('colorbox-div')).style.display).toBe('block');
  });
});
